// The Atlax look on iOS: black and white like every Atlax surface (no accent
// colour), the real mark (MarkPath, generated by icon.ts from the master
// vector), and the few tokens the app, the widgets and the controls share.
import SwiftUI

enum Brand {
    static let bg = Color.black
    static let fg = Color.white
    /// Secondary text and icons.
    static let dim = Color.white.opacity(0.56)
    /// Tertiary: hints, timestamps, disabled.
    static let faint = Color.white.opacity(0.34)
    /// Raised surfaces (cards, rows, bubbles) and their hairline.
    static let surface = Color.white.opacity(0.06)
    static let raised = Color.white.opacity(0.10)
    static let line = Color.white.opacity(0.10)
    /// Corner radii: cards, tiles, controls.
    static let r = (card: CGFloat(18), tile: CGFloat(14), small: CGFloat(10))
}

/// The Atlax "A", drawn from the master path (nonzero fill), aspect kept and
/// centred in whatever frame it gets.
struct AtlaxMarkShape: Shape {
    private static let unit: (path: Path, box: CGRect) = {
        var p = Path()
        // Tokens: a command letter or a signed number (potrace writes integers).
        var tok: [String] = []
        var n = ""
        for ch in MarkPath.d {
            if ch.isLetter {
                if !n.isEmpty { tok.append(n); n = "" }
                tok.append(String(ch))
            } else if ch == "-" {
                if !n.isEmpty { tok.append(n) }
                n = "-"
            } else if ch.isNumber || ch == "." {
                n.append(ch)
            } else if !n.isEmpty {
                tok.append(n); n = ""
            }
        }
        if !n.isEmpty { tok.append(n) }
        var i = 0, cmd: Character = "M"
        var x = 0.0, y = 0.0
        func num() -> Double { defer { i += 1 }; return Double(tok[i]) ?? 0 }
        // y-up path units -> y-down.
        func pt(_ a: Double, _ b: Double) -> CGPoint { CGPoint(x: a, y: -b) }
        while i < tok.count {
            if let l = tok[i].first, l.isLetter { cmd = l; i += 1 }
            switch cmd {
            case "M":
                x = num(); y = num(); p.move(to: pt(x, y)); cmd = "L"
            case "m":
                x += num(); y += num(); p.move(to: pt(x, y)); cmd = "l"
            case "L":
                x = num(); y = num(); p.addLine(to: pt(x, y))
            case "l":
                x += num(); y += num(); p.addLine(to: pt(x, y))
            case "c":
                let x1 = x + num(), y1 = y + num(), x2 = x + num(), y2 = y + num()
                x += num(); y += num()
                p.addCurve(to: pt(x, y), control1: pt(x1, y1), control2: pt(x2, y2))
            case "z", "Z":
                p.closeSubpath()
            default:
                i += 1
            }
        }
        return (p, p.boundingRect)
    }()

    func path(in rect: CGRect) -> Path {
        let (p, b) = Self.unit
        guard b.width > 0, b.height > 0 else { return Path() }
        let k = min(rect.width / b.width, rect.height / b.height)
        let t = CGAffineTransform(translationX: rect.midX - b.midX * k, y: rect.midY - b.midY * k).scaledBy(x: k, y: k)
        return p.applying(t)
    }
}

/// The mark alone, white (or the current foreground) at a given height.
struct AtlaxMark: View {
    var size: CGFloat = 28
    var body: some View {
        AtlaxMarkShape().fill(.foreground).frame(width: size * 0.83, height: size)
            .accessibilityLabel("Atlax")
    }
}

/// The app-icon look: the mark on a black tile with a hairline.
struct LogoMark: View {
    var size: CGFloat = 40

    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: size * 0.24, style: .continuous).fill(Color.black)
            RoundedRectangle(cornerRadius: size * 0.24, style: .continuous)
                .strokeBorder(Brand.line, lineWidth: max(0.5, size / 64))
            AtlaxMarkShape().fill(Color.white).frame(width: size * 0.56, height: size * 0.56)
        }
        .frame(width: size, height: size)
        .accessibilityLabel("Atlax")
    }
}
